import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { router } from 'kea-router'

import { urls } from 'scenes/urls'

import { dataQualityOverviewLogic } from 'products/data_quality/frontend/overview/dataQualityOverviewLogic'

import { CatalogTableRow, DATA_QUALITY_TAB, TABLES_SEARCH_PARAM } from '../catalogTableRows'
import { catalogTablesLogic } from '../catalogTablesLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface catalogDataQualityLogicValues {
    rows: CatalogTableRow[] // catalogTablesLogic
    rowsError: string | null // catalogTablesLogic
    rowsLoaded: boolean // catalogTablesLogic
    searchParams: Record<string, any> // router
    checkedRows: CatalogTableRow[]
    expandedTableKeys: string[]
    tableFilter: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface catalogDataQualityLogicActions {
    runChecks: (
        target: import('products/data_quality/frontend/overview/dataQualityOverviewLogic').OverviewRunTarget,
        checkIds?: string[] | undefined
    ) => {
        checkIds: string[]
        target: import('products/data_quality/frontend/overview/dataQualityOverviewLogic').OverviewRunTarget
    } // dataQualityOverviewLogic
    runTableChecks: (row: CatalogTableRow) => {
        row: CatalogTableRow
    }
    showAllTables: () => {
        value: true
    }
    toggleTableExpanded: (rowKey: string) => {
        rowKey: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface catalogDataQualityLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        tableFilter: (searchParams: Record<string, any>) => string | null
        checkedRows: (rows: CatalogTableRow[], tableFilter: string | null) => CatalogTableRow[]
    }
}

export type catalogDataQualityLogicType = MakeLogicType<
    catalogDataQualityLogicValues,
    catalogDataQualityLogicActions,
    Record<string, any>,
    catalogDataQualityLogicMeta
>

export const catalogDataQualityLogic = kea<catalogDataQualityLogicType>([
    path(['products', 'data_catalog', 'frontend', 'dataQuality', 'catalogDataQualityLogic']),
    connect(() => ({
        values: [catalogTablesLogic, ['rows', 'rowsLoaded', 'rowsError'], router, ['searchParams']],
        actions: [dataQualityOverviewLogic, ['runChecks']],
    })),
    actions({
        toggleTableExpanded: (rowKey: string) => ({ rowKey }),
        runTableChecks: (row: CatalogTableRow) => ({ row }),
        showAllTables: true,
    }),
    reducers({
        expandedTableKeys: [
            [] as string[],
            {
                toggleTableExpanded: (state, { rowKey }) =>
                    state.includes(rowKey) ? state.filter((key) => key !== rowKey) : [...state, rowKey],
                runTableChecks: (state, { row }) => (state.includes(row.key) ? state : [...state, row.key]),
            },
        ],
    }),
    selectors({
        tableFilter: [
            (s) => [s.searchParams],
            (searchParams: Record<string, any>): string | null => {
                const table = searchParams[TABLES_SEARCH_PARAM]
                return searchParams.tab === DATA_QUALITY_TAB && typeof table === 'string' ? table : null
            },
        ],
        checkedRows: [
            (s) => [s.rows, s.tableFilter],
            (rows: CatalogTableRow[], tableFilter: string | null): CatalogTableRow[] =>
                tableFilter ? rows.filter((row) => row.name === tableFilter) : rows.filter((row) => row.checkGroup),
        ],
    }),
    listeners(({ actions, values }) => ({
        runTableChecks: ({ row }) => {
            if (!row.checkGroup) {
                return
            }
            actions.runChecks(
                { kind: 'subject', subjectKey: row.checkGroup.subjectKey },
                row.checkGroup.checks.map((check) => check.id)
            )
        },
        showAllTables: () => {
            router.actions.replace(urls.dataCatalog(), { ...values.searchParams, [TABLES_SEARCH_PARAM]: undefined })
        },
    })),
])
